import pytest
from src.retry import retry

def test_no_retry_needed():
    calls = []
    @retry(3)
    def fn():
        calls.append(1)
        return 42
    assert fn() == 42
    assert len(calls) == 1

def test_retries_on_exception():
    calls = []
    @retry(3, exceptions=(ValueError,))
    def fn():
        calls.append(1)
        if len(calls) < 3:
            raise ValueError('fail')
        return 'ok'
    assert fn() == 'ok'
    assert len(calls) == 3

def test_raises_after_max():
    @retry(2, exceptions=(RuntimeError,))
    def fn():
        raise RuntimeError('always fails')
    with pytest.raises(RuntimeError):
        fn()

def test_does_not_catch_other_exceptions():
    @retry(3, exceptions=(ValueError,))
    def fn():
        raise TypeError('wrong type')
    with pytest.raises(TypeError):
        fn()

def test_preserves_return_value():
    @retry(1)
    def fn(x, y):
        return x + y
    assert fn(3, 4) == 7
